const d = $json.output ?? $json;
const required = ['volumen_mensual','minutos_por_caso','costo_hora_humano_usd','costo_setup_estimado_usd','costo_ia_mensual_estimado_usd'];
const faltantes = Array.isArray(d.faltantes) ? [...d.faltantes] : [];
for (const k of required) {
  if (d[k] === null || d[k] === undefined || d[k] === '') {
    if (!faltantes.includes(k)) faltantes.push(k);
  }
}
return [{
  json: {
    ...d,
    chat_id: $('Capturar solicitud Telegram').item.json.chat_id,
    discovery_completo: faltantes.length === 0,
    faltantes
  }
}];

const d = $json;

const volumen = Number(d.volumen_mensual || 0);
const minCaso = Number(d.minutos_por_caso || 0);
const costoHora = Number(d.costo_hora_humano_usd || 0);
const setup = Number(d.costo_setup_estimado_usd || 0);
const ia = Number(d.costo_ia_mensual_estimado_usd || 0);
const infra = Number(d.costo_infra_mensual_estimado_usd || 0);
const soporteHoras = Number(d.horas_soporte_mensual_estimadas || 0);
const soporteHora = Number(d.costo_hora_soporte_usd || 0);
const soporte = soporteHoras * soporteHora;
const costoManual = volumen * (minCaso / 60) * costoHora;
const tcoBase = ia + infra + soporte;

function escenario(nombre, factorVolumen, automatizacion, factorCostoIA) {
  const volumenEsc = volumen * factorVolumen;
  const valorCapacidad = volumenEsc * (minCaso / 60) * costoHora * automatizacion;
  const tco = (ia * factorCostoIA) + infra + soporte;
  const beneficioNeto = valorCapacidad - tco;
  const roiMensual = tco > 0 ? (beneficioNeto / tco) * 100 : null;
  const payback = beneficioNeto > 0 ? setup / beneficioNeto : null;
  const costoEjecucion = volumenEsc > 0 ? tco / volumenEsc : null;
  return {
    nombre,
    volumen_estimado: Math.round(volumenEsc),
    tasa_automatizacion_pct: automatizacion * 100,
    capacidad_liberada_usd_mes: Number(valorCapacidad.toFixed(2)),
    tco_mensual_usd: Number(tco.toFixed(2)),
    beneficio_neto_mensual_usd: Number(beneficioNeto.toFixed(2)),
    roi_mensual_pct: roiMensual === null ? null : Number(roiMensual.toFixed(1)),
    payback_meses: payback === null ? null : Number(payback.toFixed(1)),
    costo_por_ejecucion_usd: costoEjecucion === null ? null : Number(costoEjecucion.toFixed(4))
  };
}

const escenarios = [
  escenario('CONSERVADOR', 0.70, 0.60, 1.20),
  escenario('BASE', 1.00, 0.80, 1.00),
  escenario('OPTIMISTA', 1.20, 0.90, 0.90),
];

return [{
  json: {
    ...d,
    baseline: {
      costo_manual_mensual_usd: Number(costoManual.toFixed(2)),
      horas_manual_mes: Number((volumen * minCaso / 60).toFixed(1))
    },
    tco_componentes: {
      ia_mensual_usd: ia,
      infraestructura_mensual_usd: infra,
      soporte_mensual_usd: Number(soporte.toFixed(2))
    },
    escenarios
  }
}];

const d = $json;
const base = d.escenarios?.find(e => e.nombre === 'BASE') || {};
const setup = Number(d.costo_setup_estimado_usd || 0);
const retainer = Math.max(
  Number((base.tco_mensual_usd || 0) * 1.8),
  Number(d.costo_ia_mensual_estimado_usd || 0) + Number(d.costo_infra_mensual_estimado_usd || 0)
);
const successUnit = Number(d.success_fee_unitario_usd || 0);

return [{
  json: {
    ...d,
    modelo_comercial: {
      recomendado: 'HIBRIDO',
      setup_fee_usd: setup,
      retainer_mensual_recomendado_usd: Number(retainer.toFixed(2)),
      success_fee_kpi: d.kpi_success_fee || 'Conversión atribuible asistida por IA',
      success_fee_unitario_usd: successUnit || null,
      ventana_conversion_dias: Number(d.ventana_conversion_dias || 30),
      incluye_retainer: [
        'Prompt tuning basado en logs',
        'Knowledge refresh',
        'Model management',
        'Observabilidad activa',
        'Revisión de AI-as-a-Judge',
        'Adaptación a cambios externos de APIs/LLMs'
      ]
    }
  }
}];

const d = $json;
const stakeholders = (d.stakeholders && d.stakeholders.length) ? d.stakeholders : ['CFO','COO','CTO/CISO','Usuarios finales'];

const matriz = {
  'CFO': {
    preocupacion: 'ROI, TCO, coste marginal y payback',
    mensaje: 'La propuesta convierte capacidad operativa en valor medible y controla el coste de escala.'
  },
  'COO': {
    preocupacion: 'Fiabilidad, excepciones y continuidad operativa',
    mensaje: 'El sistema automatiza casos estándar y escala los complejos, reduciendo cuellos de botella.'
  },
  'CTO/CISO': {
    preocupacion: 'Seguridad, auditoría, gobernanza y residencia de datos',
    mensaje: 'Arquitectura auditable, guardrails, trazabilidad y posibilidad de self-hosting.'
  },
  'Usuarios finales': {
    preocupacion: 'Dificultad de uso y temor a reemplazo',
    mensaje: 'La IA elimina tareas repetitivas y deja las decisiones sensibles en manos humanas.'
  }
};

return [{
  json: {
    ...d,
    roadmap: [
      {
        fase: 0,
        nombre: 'Shadowing',
        puede: 'Leer entradas y proponer respuestas',
        prohibido: 'Ejecutar acciones o responder sin validación',
        valida: 'Humano',
        criterio_salida: 'Dataset real suficiente + precisión objetivo definida'
      },
      {
        fase: 1,
        nombre: 'Piloto Solo Lectura',
        puede: 'Responder FAQs y consultar conocimiento corporativo',
        prohibido: 'Modificar CRM, cancelar, crear o borrar registros',
        valida: 'AI-as-a-Judge + muestreo humano',
        criterio_salida: 'Precisión estable y tasa de fallback aceptable'
      },
      {
        fase: 2,
        nombre: 'Escritura Controlada',
        puede: 'Crear acciones permitidas: agenda, contacto, actualización acotada',
        prohibido: 'Acciones irreversibles sin aprobación',
        valida: 'Human-in-the-Loop',
        criterio_salida: 'Baja tasa de errores + trazabilidad completa'
      },
      {
        fase: 3,
        nombre: 'Autonomía Supervisada',
        puede: 'Operar dentro de guardrails definidos',
        prohibido: 'Salir del alcance autorizado',
        valida: 'AI-as-a-Judge + observabilidad + HITL por excepción',
        criterio_salida: 'Operación sostenida dentro de SLA'
      }
    ],
    fallback: [
      'Timeout del modelo → reintento controlado',
      'Falta de contexto → no inventar y derivar',
      'Riesgo alto → HITL',
      'API externa caída → cola/reintento + alerta'
    ],
    stakeholder_matrix: stakeholders.map(s => ({
      stakeholder: s,
      ...(matriz[s] || {preocupacion:'Valor, riesgo y control', mensaje:'La solución se adapta a su objetivo de negocio con métricas y guardrails.'})
    }))
  }
}];

return [{
  json: {
    brochure: $json.text ?? $json.output ?? $json,
    retry_count: Number($json.retry_count ?? 0),
    chat_id: $('Capturar solicitud Telegram').item.json.chat_id,
    business_case: $('Roadmap + Stakeholders').item.json
  }
}];

const j = $('AI-as-a-Judge - Brochure').item.json.output ?? $('AI-as-a-Judge - Brochure').item.json;
const evalIn = $('Preparar evaluación').item.json;
const bc = $('Roadmap + Stakeholders').item.json;
const base = bc.escenarios.find(e => e.nombre === 'BASE') || {};

const texto = `✅ PROPUESTA APROBADA POR EL AI-as-a-JUDGE

Cliente: ${bc.cliente || 'No informado'}
Score: ${j.score_total_100 ?? 'N/D'}/100

📊 BUSINESS CASE BASE
• Horas manuales/mes: ${bc.baseline?.horas_manual_mes ?? 'N/D'}
• Capacidad liberada: USD ${base.capacidad_liberada_usd_mes ?? 'N/D'}/mes
• TCO: USD ${base.tco_mensual_usd ?? 'N/D'}/mes
• Beneficio neto: USD ${base.beneficio_neto_mensual_usd ?? 'N/D'}/mes
• ROI mensual: ${base.roi_mensual_pct ?? 'N/D'}%
• Payback: ${base.payback_meses ?? 'N/D'} meses

💼 MODELO COMERCIAL
• Setup: USD ${bc.modelo_comercial?.setup_fee_usd ?? 'N/D'}
• Retainer sugerido: USD ${bc.modelo_comercial?.retainer_mensual_recomendado_usd ?? 'N/D'}/mes
• Success fee KPI: ${bc.modelo_comercial?.success_fee_kpi ?? 'A definir'}
• Ventana: ${bc.modelo_comercial?.ventana_conversion_dias ?? 'N/D'} días

🧭 ROADMAP
0 Shadow → 1 Solo lectura → 2 Escritura controlada + HITL → 3 Autonomía supervisada

📌 RECOMENDACIÓN
Usar despliegue incremental, baseline explícito, trazabilidad CRM y pricing híbrido.

---
BROCHURE EJECUTIVO

${evalIn.brochure}`;

return [{json:{chat_id: evalIn.chat_id, mensaje_final: texto}}];

const j = $json.output ?? $json;
const prev = $('Preparar evaluación').item.json;
const nextRetry = Number(prev.retry_count || 0) + 1;
return [{
  json: {
    feedback_correccion: j.feedback || 'Revisar faltantes detectados por el auditor.',
    retry_count: nextRetry,
    chat_id: prev.chat_id
  }
}];
